(() => {
  'use strict';
  const STATE_KEY='insureclub_crm_state_v2';
  const LEGACY={customers:'insureclub_customers_v1',policies:'insureclub_policies_v1',meetings:'insureclub_meetings_v1',advisor:'insureclub_advisor_name_v1'};
  const ARRAYS=['customers','familyMembers','policies','policyHistory','reminders','appointments','activities','messageTemplates','companies','products','categories','portingReminders'];
  const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
  const uid=p=>`${p}-${Date.now()}-${Math.random().toString(16).slice(2,8)}`;
  const esc=(v='')=>String(v).replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
  const isoNow=()=>new Date().toISOString();
  const dateOnly=d=>{const x=new Date(d);return `${x.getFullYear()}-${String(x.getMonth()+1).padStart(2,'0')}-${String(x.getDate()).padStart(2,'0')}`};
  const today=()=>dateOnly(new Date());
  const fmtDate=v=>v?new Date(`${String(v).slice(0,10)}T12:00:00`).toLocaleDateString('en-IN',{day:'numeric',month:'short',year:'numeric'}):'Not set';
  const fmtDateTime=v=>v?new Date(v).toLocaleString('en-IN',{day:'numeric',month:'short',year:'numeric',hour:'numeric',minute:'2-digit'}):'Not set';
  const money=v=>new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',maximumFractionDigits:0}).format(Number(v)||0);
  const daysBetween=(a,b)=>Math.floor((new Date(`${String(a).slice(0,10)}T12:00:00`)-new Date(`${String(b).slice(0,10)}T12:00:00`))/86400000);
  const initials=n=>String(n||'CL').split(/\s+/).filter(Boolean).slice(0,2).map(x=>x[0]).join('').toUpperCase();
  const age=d=>{if(!d)return '—';const b=new Date(`${d}T12:00:00`),n=new Date();let a=n.getFullYear()-b.getFullYear();if(n<new Date(n.getFullYear(),b.getMonth(),b.getDate()))a--;return Math.max(0,a)};
  const selectOptions=(items,value,label='name')=>items.map(x=>`<option value="${esc(x.id)}" ${x.id===value?'selected':''}>${esc(x[label]||x.name)}</option>`).join('');
  const customerBy=id=>state.customers.find(x=>x.id===id);
  const policyBy=id=>state.policies.find(x=>x.id===id);

  function baseState(){return {schemaVersion:2,updatedAt:isoNow(),advisorName:'Manpreet Singh',customers:[],familyMembers:[],policies:[],policyHistory:[],reminders:[],appointments:[],activities:[],companies:[],products:[],categories:[],portingReminders:[],backupMetadata:{},messageTemplates:[
    {id:uid('tpl'),type:'Birthday',name:'Birthday greeting',body:'Dear {{customer_name}}, wishing you a very happy birthday, good health and a wonderful year ahead. Warm regards, {{agent_name}}',isDefault:true},
    {id:uid('tpl'),type:'Renewal',name:'Policy renewal',body:'Dear {{customer_name}}, your {{company_name}} {{product_name}} policy {{policy_number}} is due for renewal on {{renewal_date}}. The premium is {{premium}}. Please let me know how I can assist. Regards, {{agent_name}}',isDefault:true},
    {id:uid('tpl'),type:'Anniversary',name:'Anniversary greeting',body:'Dear {{customer_name}}, warm wishes to you and your family on your anniversary. Regards, {{agent_name}}',isDefault:true},
    {id:uid('tpl'),type:'Appointment request',name:'Appointment request',body:'Dear {{customer_name}}, may we schedule a discussion on {{appointment_date}} regarding your insurance requirements? Regards, {{agent_name}}',isDefault:true}
  ]};}

  function loadState(){
    try{const stored=JSON.parse(localStorage.getItem(STATE_KEY)||'null');if(stored?.schemaVersion>=2){ARRAYS.forEach(k=>stored[k]=Array.isArray(stored[k])?stored[k]:[]);return stored}}catch{}
    const s=baseState();
    try{s.customers=JSON.parse(localStorage.getItem(LEGACY.customers)||'[]').map(x=>({...x,createdAt:x.createdAt||isoNow()}));}catch{}
    try{s.policies=JSON.parse(localStorage.getItem(LEGACY.policies)||'[]').map(x=>({...x,companyName:x.companyName||x.provider||'',productName:x.productName||x.planName||'',categoryName:x.categoryName||'',startDate:x.startDate||x.createdAt?.slice(0,10)||today(),status:/renewed/i.test(x.status||'')?'Historical':'Active'}));}catch{}
    try{s.appointments=JSON.parse(localStorage.getItem(LEGACY.meetings)||'[]').map(x=>({...x,purpose:x.purpose||x.title||'Meeting',reminderAt:x.reminderAt||`${x.date}T09:00`,status:x.status||'Scheduled'}));}catch{}
    s.advisorName=localStorage.getItem(LEGACY.advisor)||s.advisorName;return s;
  }
  let state=loadState(), activeRoute='home', activeReminderFilter='Today', profile={customerId:null,tab:'Overview'}, formSubmit=null, pendingImportSummary=null;

  function addActivity(customerId,text,type='Activity'){if(!customerId)return;state.activities.unshift({id:uid('act'),customerId,type,text,createdAt:isoNow()});}
  function ensureReference(name,key){const value=String(name||'').trim();if(!value)return;const list=state[key];if(!list.some(x=>x.name.toLowerCase()===value.toLowerCase()))list.push({id:uid(key.slice(0,3)),name:value});}
  function annualDate(v){if(!v)return null;const source=new Date(`${v}T12:00:00`),now=new Date();let d=new Date(now.getFullYear(),source.getMonth(),source.getDate());if(dateOnly(d)<today())d=new Date(now.getFullYear()+1,source.getMonth(),source.getDate());return dateOnly(d)}

  function ensureAutomaticReminders(){
    const desired=[];
    state.customers.forEach(c=>[['Birthday',c.dateOfBirth],['Anniversary',c.anniversaryDate]].forEach(([type,v])=>{const due=annualDate(v);if(due)desired.push({id:`auto-${type}-${c.id}-${due}`,customerId:c.id,customerName:c.name,type,activity:`${type} message`,dueAt:`${due}T08:00`,status:'Pending',auto:true})}));
    state.familyMembers.forEach(f=>{const due=annualDate(f.dateOfBirth),c=customerBy(f.customerId);if(due&&c)desired.push({id:`auto-Family-${f.id}-${due}`,customerId:c.id,customerName:c.name,familyMemberId:f.id,type:'Birthday',activity:`Birthday message · ${f.fullName}`,dueAt:`${due}T08:00`,status:'Pending',auto:true})});
    state.policies.filter(p=>p.status==='Active'&&p.renewalDueDate).forEach(p=>[30,15,7,3,0].forEach(lead=>{const d=new Date(`${p.renewalDueDate}T12:00:00`);d.setDate(d.getDate()-lead);desired.push({id:`auto-Renewal-${p.id}-${p.renewalDueDate}-${lead}`,customerId:p.customerId,customerName:p.customerName,policyId:p.id,type:'Renewal',activity:lead?`Renewal · ${lead} days remaining`:'Renewal due today',dueAt:`${dateOnly(d)}T09:00`,status:'Pending',auto:true})}));
    state.appointments.filter(a=>!['Completed','Cancelled'].includes(a.status)).forEach(a=>desired.push({id:`auto-Appointment-${a.id}-${a.reminderAt}`,customerId:a.customerId,customerName:a.customerName,appointmentId:a.id,type:'Appointment',activity:a.purpose,dueAt:a.reminderAt,status:'Pending',auto:true,notes:a.notes||''}));
    state.portingReminders.filter(p=>!['Ported','Not Interested','Cancelled'].includes(p.status)).forEach(p=>desired.push({id:`auto-Porting-${p.id}-${p.reminderDate}`,customerId:p.customerId,customerName:p.customerName,policyId:p.policyId,type:'Porting',activity:'Policy porting discussion',dueAt:`${p.reminderDate}T09:00`,status:'Pending',auto:true,notes:p.notes||''}));
    const completed=new Map(state.reminders.filter(r=>r.status==='Completed'||r.snoozedFrom).map(r=>[r.id,r]));
    const manual=state.reminders.filter(r=>!r.auto);
    state.reminders=[...manual,...desired.map(r=>completed.get(r.id)||r)];
  }

  function persist(reason='change',quiet=false){
    ensureAutomaticReminders();state.updatedAt=isoNow();localStorage.setItem(STATE_KEY,JSON.stringify(state));
    if(window.InsureClubNative?.syncReminders)window.InsureClubNative.syncReminders(JSON.stringify(state));
    if(window.InsureClubNative?.backupNow)window.InsureClubNative.backupNow(JSON.stringify(state),reason);
    renderAll();if(!quiet)toast('Saved securely');
  }
  window.InsureClubAppBackup=reason=>{localStorage.setItem(STATE_KEY,JSON.stringify(state));window.InsureClubNative?.backupNow?.(JSON.stringify(state),reason||'app-backgrounded')};

  function toast(message){const e=$('#toast');e.textContent=message;e.classList.add('show');clearTimeout(toast.t);toast.t=setTimeout(()=>e.classList.remove('show'),2300)}
  function empty(title,text){return `<div class="empty"><strong>${esc(title)}</strong><span>${esc(text)}</span></div>`}
  function route(name){activeRoute=name;$$('.view').forEach(v=>v.classList.toggle('active',v.id===`view-${name}`));$$('.bottom-nav button').forEach(b=>b.classList.toggle('active',b.dataset.route===name));window.scrollTo(0,0);renderAll()}
  function openForm(title,eyebrow,html,onSubmit){$('#modalTitle').textContent=title;$('#modalEyebrow').textContent=eyebrow;$('#dynamicForm').innerHTML=html;formSubmit=onSubmit;$('#formModal').classList.add('open')}
  function closeForm(){$('#formModal').classList.remove('open');formSubmit=null}
  function choice(title,text,actions){$('#choiceTitle').textContent=title;$('#choiceText').textContent=text;$('#choiceActions').innerHTML=actions.map(a=>`<button data-choice="${esc(a.id)}" class="${a.danger?'danger-outline':''}">${esc(a.label)}</button>`).join('');$('#choiceModal').classList.add('open')}
  function closeChoice(){$('#choiceModal').classList.remove('open')}

  function periodTotal(start,end){return state.policies.filter(p=>p.status==='Active'&&p.startDate&&p.startDate>=start&&p.startDate<=end).reduce((s,p)=>s+Number(p.premiumAmount||0),0)}
  function periodRange(kind,offset=0){const n=new Date(),y=n.getFullYear(),m=n.getMonth();let a,b;if(kind==='month'){a=new Date(y,m+offset,1);b=new Date(y,m+offset+1,0)}else if(kind==='quarter'){const q=Math.floor(m/3)*3+offset*3;a=new Date(y,q,1);b=new Date(y,q+3,0)}else{a=new Date(y+offset,0,1);b=new Date(y+offset,11,31)}return [dateOnly(a),dateOnly(b)]}
  function renderHome(){
    const first=state.advisorName.split(' ')[0]||'Advisor',h=new Date().getHours();$('#welcomeTitle').innerHTML=`${h<12?'Good morning':h<17?'Good afternoon':'Good evening'},<br><em>${esc(first)}.</em>`;$('#todayLabel').innerHTML=`${new Date().toLocaleDateString('en-IN',{weekday:'short'}).toUpperCase()}<br>${new Date().getDate()} ${new Date().toLocaleDateString('en-IN',{month:'short'}).toUpperCase()}`;
    $('#performanceCards').innerHTML=['month','quarter','year'].map(k=>{const [a,b]=periodRange(k),[pa,pb]=periodRange(k,-1),v=periodTotal(a,b),prev=periodTotal(pa,pb),delta=prev?Math.round((v-prev)/prev*100):null;return `<button class="metric" data-performance="${k}"><strong>${money(v)}</strong><span>THIS ${k.toUpperCase()}</span><small>${delta===null?'No prior comparison':`${delta>=0?'+':''}${delta}% vs previous`}</small></button>`}).join('');
    const pending=state.reminders.filter(r=>r.status!=='Completed'),todayItems=pending.filter(r=>String(r.dueAt).slice(0,10)===today()),upcoming=pending.filter(r=>{const d=daysBetween(String(r.dueAt).slice(0,10),today());return d>=0&&d<=30}).sort((a,b)=>a.dueAt.localeCompare(b.dueAt));
    $('#todayActivities').innerHTML=todayItems.length?todayItems.slice(0,5).map(reminderCard).join(''):empty('Today is clear','No pending activities due today.');
    $('#upcomingList').innerHTML=upcoming.length?upcoming.slice(0,5).map(reminderCard).join(''):empty('Nothing due soon','Upcoming renewals and appointments will appear here.');
  }
  function reminderCard(r){const c=customerBy(r.customerId),over=String(r.dueAt).slice(0,10)<today()&&r.status!=='Completed';return `<article class="activity-card"><span class="activity-icon">${({Birthday:'🎂',Anniversary:'♡',Renewal:'₹',Appointment:'◷',Porting:'⇄'}[r.type]||'✓')}</span><div class="activity-copy"><strong>${esc(r.customerName||c?.name||'General')} · ${esc(r.activity||r.type)}</strong><span>${fmtDateTime(r.dueAt)}${r.notes?` · ${esc(r.notes)}`:''}</span>${activeRoute==='reminders'?`<div class="reminder-actions"><button data-call="${esc(c?.phone||'')}">Call</button><button data-message-reminder="${r.id}">Message</button><button data-fix-appointment="${r.id}">Fix appointment</button><button data-snooze="${r.id}">Snooze</button><button data-complete-reminder="${r.id}">Complete</button><button data-open-customer="${esc(r.customerId||'')}">Open</button></div>`:''}</div><span class="status ${over?'overdue':r.status==='Completed'?'done':''}">${esc(r.status==='Completed'?'Done':over?'Overdue':r.type)}</span></article>`}

  function renderClients(){const term=($('#clientSearch')?.value||'').trim().toLowerCase();const filtered=state.customers.filter(c=>[c.name,c.phone,c.city,...state.familyMembers.filter(f=>f.customerId===c.id).map(f=>f.fullName)].some(v=>String(v||'').toLowerCase().includes(term)));$('#clientList').classList.toggle('hidden',Boolean(profile.customerId));if(profile.customerId){renderProfile();return}$('#clientList').innerHTML=filtered.length?filtered.map(c=>{const pol=state.policies.filter(p=>p.customerId===c.id&&p.status==='Active'),fam=state.familyMembers.filter(f=>f.customerId===c.id);return `<article class="client-card"><div class="card-head"><span class="client-avatar">${initials(c.name)}</span><div class="card-main"><strong>${esc(c.name)}</strong><span>${esc(c.phone||'No phone')} · ${esc(c.city||'City not set')}</span></div><div class="card-actions"><button class="icon-button" data-whatsapp="${c.id}">◉</button><button class="icon-button" data-open-customer="${c.id}">›</button></div></div><div class="card-foot"><span>${fam.length} family member${fam.length===1?'':'s'}</span><span>${pol.length} active polic${pol.length===1?'y':'ies'} · ${money(pol.reduce((s,p)=>s+Number(p.premiumAmount||0),0))}</span></div></article>`}).join(''):empty(term?'No matching customer':'Your CRM is ready',term?'Try another name or mobile number.':'Add your first real customer.');}
  function renderProfile(){const c=customerBy(profile.customerId);if(!c){profile.customerId=null;renderClients();return}const panel=$('#clientProfile');panel.classList.remove('hidden');const tabs=['Overview','Family','Policies','Policy History','Appointments','Reminders','Documents','Activity History'];panel.innerHTML=`<div class="profile-hero"><button class="icon-button" data-close-profile>←</button><h2>${esc(c.name)}</h2><p>${esc(c.phone||'No phone')} · ${esc(c.city||'City not set')}</p></div><div class="profile-tabs">${tabs.map(t=>`<button data-profile-tab="${t}" class="${profile.tab===t?'active':''}">${t}</button>`).join('')}</div><div class="profile-content">${profileTab(c)}</div>`;}
  function profileTab(c){const active=state.policies.filter(p=>p.customerId===c.id&&p.status==='Active'),fam=state.familyMembers.filter(f=>f.customerId===c.id),apps=state.appointments.filter(a=>a.customerId===c.id),rems=state.reminders.filter(r=>r.customerId===c.id),hist=state.policyHistory.filter(p=>p.customerId===c.id),acts=state.activities.filter(a=>a.customerId===c.id);if(profile.tab==='Overview'){const nextRenewal=active.filter(p=>p.renewalDueDate).sort((a,b)=>a.renewalDueDate.localeCompare(b.renewalDueDate))[0],nextApp=apps.filter(a=>a.status==='Scheduled').sort((a,b)=>a.date.localeCompare(b.date))[0];return `<div class="info-grid"><div class="info-box"><span>Date of birth</span><strong>${fmtDate(c.dateOfBirth)}</strong></div><div class="info-box"><span>Anniversary</span><strong>${fmtDate(c.anniversaryDate)}</strong></div><div class="info-box"><span>Family</span><strong>${fam.length}</strong></div><div class="info-box"><span>Active policies</span><strong>${active.length}</strong></div><div class="info-box"><span>Total premium</span><strong>${money(active.reduce((s,p)=>s+Number(p.premiumAmount||0),0))}</strong></div><div class="info-box"><span>Upcoming renewal</span><strong>${fmtDate(nextRenewal?.renewalDueDate)}</strong></div><div class="info-box"><span>Next appointment</span><strong>${fmtDate(nextApp?.date)}</strong></div><div class="info-box"><span>Pending reminders</span><strong>${rems.filter(r=>r.status!=='Completed').length}</strong></div></div><div class="inline-actions"><button data-edit-customer="${c.id}">Edit customer</button><button data-family-new="${c.id}">Add family</button><button data-policy-new="${c.id}">Add policy</button><button data-appointment-new="${c.id}">Appointment</button><button class="danger" data-delete-customer="${c.id}">Delete</button></div>`}
    if(profile.tab==='Family')return `<div class="inline-actions"><button data-family-new="${c.id}">Add family member</button></div>${fam.length?fam.map(f=>record(`${f.fullName} · ${f.relationship}`,`DOB ${fmtDate(f.dateOfBirth)} · Age ${age(f.dateOfBirth)}${f.mobile?` · ${f.mobile}`:''}`,`<button data-family-edit="${f.id}">Edit</button><button class="danger" data-family-delete="${f.id}">Delete</button>`)).join(''):empty('No family members','Add family members to include their birthdays.')}`;
    if(profile.tab==='Policies')return `<div class="inline-actions"><button data-policy-new="${c.id}">Add policy</button></div>${active.length?active.map(policyRow).join(''):empty('No active policies','Add a policy to start renewal tracking.')}`;
    if(profile.tab==='Policy History')return hist.length?hist.map(p=>record(`${p.companyName} · ${p.productName}`,`${p.policyNumber||'No number'} · ${fmtDate(p.renewalDueDate)} · ${money(p.premiumAmount)}`,'')).join(''):empty('No policy history','Renewed policies remain available here.') ;
    if(profile.tab==='Appointments')return `<div class="inline-actions"><button data-appointment-new="${c.id}">Fix appointment</button></div>${apps.length?apps.map(a=>record(`${a.purpose} · ${a.status}`,`${fmtDate(a.date)} ${a.time||''} · ${a.notes||''}`,`<button data-appointment-edit="${a.id}">Edit</button>`)).join(''):empty('No appointments','Schedule a sales or service appointment.')}`;
    if(profile.tab==='Reminders')return `<div class="inline-actions"><button data-reminder-new="${c.id}">Add reminder</button></div>${rems.length?rems.map(r=>record(`${r.activity} · ${r.status}`,fmtDateTime(r.dueAt),r.status!=='Completed'?`<button data-complete-reminder="${r.id}">Complete</button>`:'')).join(''):empty('No reminders','Add a follow-up or service reminder.')}`;
    if(profile.tab==='Documents')return active.length?active.map(p=>record(`${p.companyName} · ${p.productName}`,p.hasDocument?`PDF · ${p.documentName}`:'No PDF attached',p.hasDocument?`<button data-view-pdf="${p.id}">View</button><button data-download-pdf="${p.id}">Download</button><button data-share-pdf="${p.id}">Share</button><button data-add-pdf="${p.id}">Replace</button><button class="danger" data-delete-pdf="${p.id}">Delete</button>`:`<button data-add-pdf="${p.id}">Add policy PDF</button>`)).join(''):empty('No policies','Add a policy before attaching its PDF.');
    return acts.length?acts.map(a=>record(a.text,fmtDateTime(a.createdAt),'')).join(''):empty('No activity yet','Major customer operations are recorded automatically.');}
  function record(title,text,actions){return `<div class="record-row"><div class="row-top"><strong>${esc(title)}</strong></div><p>${esc(text)}</p>${actions?`<div class="inline-actions">${actions}</div>`:''}</div>`}
  function policyRow(p){const remaining=daysBetween(p.renewalDueDate,today()),stage=remaining<0?'Overdue':remaining===0?'Due today':remaining<=3?'3 days remaining':remaining<=7?'7 days remaining':remaining<=15?'15 days remaining':remaining<=30?'30 days remaining':'Active';return record(`${p.companyName||'Company'} · ${p.productName||'Product'}`,`${p.policyNumber||'No policy number'} · ${money(p.premiumAmount)} · Renewal ${fmtDate(p.renewalDueDate)} · ${stage}`,`<button data-policy-edit="${p.id}">Edit</button><button data-policy-renew="${p.id}">Renew policy</button><button data-porting-new="${p.id}">Remind for porting</button><button data-add-pdf="${p.id}">${p.hasDocument?'Replace PDF':'Add PDF'}</button><button class="danger" data-policy-delete="${p.id}">Delete</button>`)}

  function renderSearch(){const q=($('#globalSearch')?.value||'').trim().toLowerCase(),company=$('#searchCompany')?.value||'',category=$('#searchCategory')?.value||'',status=$('#searchStatus')?.value||'',month=$('#searchMonth')?.value||'';const results=[];state.customers.forEach(c=>{const fields=[['customer name',c.name],['mobile',c.phone],['city',c.city]],fam=state.familyMembers.filter(f=>f.customerId===c.id);fields.push(...fam.map(f=>['family member',f.fullName]));const hit=!q?null:fields.find(([,v])=>String(v||'').toLowerCase().includes(q));if(hit)results.push({title:c.name,sub:c.phone||'',reason:`Matched ${hit[0]}: ${hit[1]}`,customerId:c.id})});state.policies.forEach(p=>{if(company&&p.companyName!==company||category&&p.categoryName!==category||status&&p.status!==status||month&&String(new Date(`${p.renewalDueDate}T12:00:00`).getMonth()+1)!==month)return;const fields=[['policy number',p.policyNumber],['company',p.companyName],['product',p.productName],['category',p.categoryName],['customer',p.customerName]],hit=q?fields.find(([,v])=>String(v||'').toLowerCase().includes(q)):['filters','Selected filters'];if(hit)results.push({title:`${p.customerName} · ${p.productName}`,sub:`${p.companyName} · ${p.policyNumber||'No number'}`,reason:`Matched ${hit[0]}: ${hit[1]}`,customerId:p.customerId})});$('#searchResults').innerHTML=results.length?results.map(r=>`<article class="result-card" data-open-customer="${r.customerId}"><strong>${esc(r.title)}</strong><p>${esc(r.sub)}</p><div class="result-reason">${esc(r.reason)}</div></article>`).join(''):empty(q||company||category||status||month?'No matching records':'Search your whole CRM','Use any part of a name, number, company, product or category.');}
  function renderReminders(){const now=today(),tom=new Date();tom.setDate(tom.getDate()+1);const tomorrow=dateOnly(tom);let list=state.reminders.slice();const f=activeReminderFilter;if(f==='Today')list=list.filter(r=>String(r.dueAt).slice(0,10)===now&&r.status!=='Completed');else if(f==='Tomorrow')list=list.filter(r=>String(r.dueAt).slice(0,10)===tomorrow&&r.status!=='Completed');else if(f==='This Week')list=list.filter(r=>{const d=daysBetween(String(r.dueAt).slice(0,10),now);return d>=0&&d<=7&&r.status!=='Completed'});else if(f==='Overdue')list=list.filter(r=>String(r.dueAt).slice(0,10)<now&&r.status!=='Completed');else if(f==='Completed')list=list.filter(r=>r.status==='Completed');else if(!['All'].includes(f))list=list.filter(r=>r.type===f&&r.status!=='Completed');list.sort((a,b)=>a.dueAt.localeCompare(b.dueAt));$('#reminderList').innerHTML=list.length?list.map(reminderCard).join(''):empty(`No ${f.toLowerCase()} reminders`,'This queue is clear.');$$('#reminderFilters button').forEach(b=>b.classList.toggle('active',b.dataset.filter===f));const count=state.reminders.filter(r=>r.status!=='Completed'&&String(r.dueAt).slice(0,10)<=now).length;$('#reminderBadge').textContent=count?String(Math.min(count,99)):'';}
  function fillSelects(){const val=id=>$(id)?.value||'';const mc=val('#messageClient'),mp=val('#messagePolicy'),mt=val('#messageTemplate');$('#messageClient').innerHTML='<option value="">Select customer</option>'+selectOptions(state.customers,mc);if(state.customers.some(x=>x.id===mc))$('#messageClient').value=mc;const policies=state.policies.filter(p=>!mc||p.customerId===mc);$('#messagePolicy').innerHTML='<option value="">Optional policy</option>'+selectOptions(policies,mp,'productName');if(policies.some(x=>x.id===mp))$('#messagePolicy').value=mp;$('#messageTemplate').innerHTML='<option value="">Select template</option>'+selectOptions(state.messageTemplates,mt);if(state.messageTemplates.some(x=>x.id===mt))$('#messageTemplate').value=mt;$('#searchCompany').innerHTML='<option value="">All companies</option>'+state.companies.map(x=>`<option>${esc(x.name)}</option>`).join('');$('#searchCategory').innerHTML='<option value="">All categories</option>'+state.categories.map(x=>`<option>${esc(x.name)}</option>`).join('');if(!$('#searchMonth').dataset.ready){$('#searchMonth').innerHTML='<option value="">Any renewal month</option>'+Array.from({length:12},(_,i)=>`<option value="${i+1}">${new Date(2020,i,1).toLocaleDateString('en-IN',{month:'long'})}</option>`).join('');$('#searchMonth').dataset.ready='1'}}
  function resolveTemplate(){const c=customerBy($('#messageClient').value),p=policyBy($('#messagePolicy').value),t=state.messageTemplates.find(x=>x.id===$('#messageTemplate').value);if(!t){$('#messagePreview').value='';return}const family=state.familyMembers.find(f=>f.customerId===c?.id),app=state.appointments.find(a=>a.customerId===c?.id&&a.status==='Scheduled');const vars={customer_name:c?.name||'',family_member_name:family?.fullName||'',policy_number:p?.policyNumber||'',company_name:p?.companyName||'',product_name:p?.productName||'',premium:money(p?.premiumAmount||0),renewal_date:fmtDate(p?.renewalDueDate),appointment_date:fmtDate(app?.date),agent_name:state.advisorName};$('#messagePreview').value=t.body.replace(/{{\s*([a-z_]+)\s*}}/g,(_,k)=>vars[k]??`{{${k}}}`)}
  function renderMessages(){fillSelects();resolveTemplate();$('#templateList').innerHTML=state.messageTemplates.length?state.messageTemplates.map(t=>`<article class="template-card"><div class="card-head"><div><strong>${esc(t.name)}</strong><span class="status">${esc(t.type)}${t.isDefault?' · Default':''}</span></div><div class="card-actions"><button class="icon-button" data-template-edit="${t.id}">•••</button></div></div><p>${esc(t.body)}</p></article>`).join(''):empty('No message templates','Add a reusable template with placeholders.');}
  function renderSettings(){ $('#advisorName').value=state.advisorName; }
  function renderAll(){ensureAutomaticReminders();renderHome();renderClients();fillSelects();renderSearch();renderReminders();renderMessages();renderSettings()}

  function customerForm(id){const c=customerBy(id)||{};openForm(c.id?'Edit customer':'Add customer','CUSTOMER PROFILE',`<input type="hidden" name="id" value="${esc(c.id||'')}"><label>Full name<input name="name" required value="${esc(c.name||'')}"></label><div class="two-col"><label>Mobile<input name="phone" inputmode="tel" required value="${esc(c.phone||'')}"></label><label>City<input name="city" value="${esc(c.city||'')}"></label></div><div class="two-col"><label>Date of birth<input name="dateOfBirth" type="date" value="${esc(c.dateOfBirth||'')}"></label><label>Anniversary<input name="anniversaryDate" type="date" value="${esc(c.anniversaryDate||'')}"></label></div><label>Notes<textarea name="notes">${esc(c.notes||'')}</textarea></label><button class="primary-button">Save customer</button>`,data=>{const current=customerBy(data.id),record={...(current||{}),id:data.id||uid('customer'),name:data.name.trim(),phone:data.phone.trim(),city:data.city.trim(),dateOfBirth:data.dateOfBirth,anniversaryDate:data.anniversaryDate,notes:data.notes.trim(),createdAt:current?.createdAt||isoNow(),updatedAt:isoNow()};state.customers=current?state.customers.map(x=>x.id===record.id?record:x):[record,...state.customers];state.policies.forEach(p=>{if(p.customerId===record.id)p.customerName=record.name});addActivity(record.id,current?'Customer profile updated':'Customer created');closeForm();persist('customer-saved')})}
  function familyForm(customerId,id){const f=state.familyMembers.find(x=>x.id===id)||{};openForm(f.id?'Edit family member':'Add family member','FAMILY',`<input type="hidden" name="id" value="${esc(f.id||'')}"><input type="hidden" name="customerId" value="${esc(customerId)}"><label>Full name<input name="fullName" required value="${esc(f.fullName||'')}"></label><label>Relationship<input name="relationship" required value="${esc(f.relationship||'')}"></label><div class="two-col"><label>Date of birth<input name="dateOfBirth" type="date" required value="${esc(f.dateOfBirth||'')}"></label><label>Mobile (optional)<input name="mobile" value="${esc(f.mobile||'')}"></label></div><label>Notes<textarea name="notes">${esc(f.notes||'')}</textarea></label><button class="primary-button">Save family member</button>`,data=>{const duplicate=state.familyMembers.find(x=>x.customerId===data.customerId&&x.id!==data.id&&x.fullName.trim().toLowerCase()===data.fullName.trim().toLowerCase()&&x.dateOfBirth===data.dateOfBirth);if(duplicate)return toast('A matching family member already exists');const current=state.familyMembers.find(x=>x.id===data.id),record={...current,id:data.id||uid('family'),customerId:data.customerId,fullName:data.fullName.trim(),relationship:data.relationship.trim(),dateOfBirth:data.dateOfBirth,mobile:data.mobile.trim(),notes:data.notes.trim()};state.familyMembers=current?state.familyMembers.map(x=>x.id===record.id?record:x):[record,...state.familyMembers];addActivity(customerId,current?`Family member updated · ${record.fullName}`:`Family member added · ${record.fullName}`);closeForm();persist('family-saved')})}
  function policyForm(customerId,id){const p=policyBy(id)||{},cid=customerId||p.customerId||'';openForm(p.id?'Edit policy':'Add policy','POLICY',`<input type="hidden" name="id" value="${esc(p.id||'')}"><label>Customer<select name="customerId" required><option value="">Select customer</option>${selectOptions(state.customers,cid)}</select></label><div class="two-col"><label>Company<input name="companyName" required value="${esc(p.companyName||'')}"></label><label>Product<input name="productName" required value="${esc(p.productName||'')}"></label></div><div class="two-col"><label>Category<input name="categoryName" required value="${esc(p.categoryName||'')}"></label><label>Policy number<input name="policyNumber" required value="${esc(p.policyNumber||'')}"></label></div><div class="two-col"><label>Start date<input name="startDate" type="date" required value="${esc(p.startDate||today())}"></label><label>Renewal date<input name="renewalDueDate" type="date" required value="${esc(p.renewalDueDate||'')}"></label></div><div class="two-col"><label>Premium ₹<input name="premiumAmount" type="number" min="0" required value="${esc(p.premiumAmount||'')}"></label><label>Sum insured ₹<input name="sumInsured" type="number" min="0" value="${esc(p.sumInsured||'')}"></label></div><label>Notes<textarea name="notes">${esc(p.notes||'')}</textarea></label><button class="primary-button">Save policy & reminders</button>`,data=>{const c=customerBy(data.customerId);if(!c)return toast('Select a valid customer');const duplicate=state.policies.find(x=>x.id!==data.id&&x.customerId===data.customerId&&x.policyNumber&&x.policyNumber.toLowerCase()===data.policyNumber.trim().toLowerCase()&&x.status==='Active');if(duplicate)return toast('This active policy number already exists');const current=policyBy(data.id),record={...current,id:data.id||uid('policy'),customerId:c.id,customerName:c.name,companyName:data.companyName.trim(),productName:data.productName.trim(),categoryName:data.categoryName.trim(),policyNumber:data.policyNumber.trim(),startDate:data.startDate,renewalDueDate:data.renewalDueDate,premiumAmount:Number(data.premiumAmount||0),sumInsured:Number(data.sumInsured||0),notes:data.notes.trim(),status:'Active',createdAt:current?.createdAt||isoNow(),updatedAt:isoNow()};state.policies=current?state.policies.map(x=>x.id===record.id?record:x):[record,...state.policies];ensureReference(record.companyName,'companies');ensureReference(record.productName,'products');ensureReference(record.categoryName,'categories');addActivity(c.id,current?`Policy updated · ${record.productName}`:`Policy added · ${record.productName}`);closeForm();persist('policy-saved')})}
  function appointmentForm(customerId,id){const a=state.appointments.find(x=>x.id===id)||{},cid=customerId||a.customerId||'';openForm(a.id?'Edit appointment':'Fix appointment','SALES & SERVICE',`<input type="hidden" name="id" value="${esc(a.id||'')}"><label>Customer<select name="customerId" required><option value="">Select customer</option>${selectOptions(state.customers,cid)}</select></label><div class="two-col"><label>Date<input name="date" type="date" required value="${esc(a.date||today())}"></label><label>Time<input name="time" type="time" required value="${esc(a.time||'10:00')}"></label></div><label>Purpose<input name="purpose" required value="${esc(a.purpose||'')}"></label><div class="two-col"><label>Product<input name="productName" value="${esc(a.productName||'')}"></label><label>Company<input name="companyName" value="${esc(a.companyName||'')}"></label></div><label>Reminder date & time<input name="reminderAt" type="datetime-local" required value="${esc(a.reminderAt||'')}"></label><label>Status<select name="status">${['Scheduled','Completed','Rescheduled','Cancelled','Customer Not Available','Follow-up Required'].map(x=>`<option ${a.status===x?'selected':''}>${x}</option>`).join('')}</select></label><label>Notes<textarea name="notes">${esc(a.notes||'')}</textarea></label><label>Next follow-up (required when follow-up needed)<input name="followUpAt" type="datetime-local" value="${esc(a.followUpAt||'')}"></label><button class="primary-button">Save appointment</button>`,data=>{if(data.status==='Follow-up Required'&&!data.followUpAt)return toast('Enter the next follow-up date and time');const c=customerBy(data.customerId),current=state.appointments.find(x=>x.id===data.id),record={...current,id:data.id||uid('appointment'),customerId:c.id,customerName:c.name,date:data.date,time:data.time,purpose:data.purpose.trim(),productName:data.productName.trim(),companyName:data.companyName.trim(),reminderAt:data.reminderAt,status:data.status,notes:data.notes.trim(),followUpAt:data.followUpAt};state.appointments=current?state.appointments.map(x=>x.id===record.id?record:x):[record,...state.appointments];if(record.status==='Follow-up Required')state.reminders.push({id:uid('reminder'),customerId:c.id,customerName:c.name,type:'Follow-up',activity:'Appointment follow-up',dueAt:record.followUpAt,status:'Pending',notes:record.notes,auto:false});addActivity(c.id,`${current?'Appointment updated':'Appointment fixed'} · ${record.purpose}`);closeForm();persist('appointment-saved')})}
  function reminderForm(customerId){openForm('Add reminder','FOLLOW-UP',`<label>Customer<select name="customerId"><option value="">General reminder</option>${selectOptions(state.customers,customerId||'')}</select></label><label>Activity type<select name="type">${['Renewal','Appointment','Sales Call','Follow-up','Document Collection','Policy Delivery','General'].map(x=>`<option>${x}</option>`).join('')}</select></label><label>Activity<input name="activity" required></label><label>Due date & time<input name="dueAt" type="datetime-local" required></label><label>Notes<textarea name="notes"></textarea></label><button class="primary-button">Save reminder</button>`,data=>{const c=customerBy(data.customerId);state.reminders.unshift({id:uid('reminder'),customerId:c?.id||'',customerName:c?.name||'General',type:data.type,activity:data.activity.trim(),dueAt:data.dueAt,status:'Pending',notes:data.notes.trim(),auto:false});if(c)addActivity(c.id,`Reminder added · ${data.activity.trim()}`);closeForm();persist('reminder-saved')})}
  function templateForm(id){const t=state.messageTemplates.find(x=>x.id===id)||{};openForm(t.id?'Edit message template':'Add message template','MESSAGE TEMPLATE',`<input type="hidden" name="id" value="${esc(t.id||'')}"><label>Template name<input name="name" required value="${esc(t.name||'')}"></label><label>Type<select name="type">${['Birthday','Policy Renewal','Anniversary','Appointment request','Renewal follow-up','Sales call follow-up','Policy porting','General follow-up'].map(x=>`<option ${t.type===x?'selected':''}>${x}</option>`).join('')}</select></label><label>Message<textarea name="body" rows="7" required>${esc(t.body||'')}</textarea></label><p class="privacy-note">Variables: {{customer_name}}, {{family_member_name}}, {{policy_number}}, {{company_name}}, {{product_name}}, {{premium}}, {{renewal_date}}, {{appointment_date}}, {{agent_name}}</p><label><input name="isDefault" type="checkbox" ${t.isDefault?'checked':''}> Set as default for this type</label><button class="primary-button">Save template</button>${t.id?`<div class="inline-actions"><button type="button" class="danger" data-template-delete="${t.id}">Delete template</button></div>`:''}`,data=>{const current=state.messageTemplates.find(x=>x.id===data.id),record={...current,id:data.id||uid('template'),name:data.name.trim(),type:data.type,body:data.body.trim(),isDefault:data.isDefault==='on'};if(record.isDefault)state.messageTemplates.forEach(x=>{if(x.type===record.type)x.isDefault=false});state.messageTemplates=current?state.messageTemplates.map(x=>x.id===record.id?record:x):[record,...state.messageTemplates];closeForm();persist('template-saved')})}
  function portingForm(policyId){const p=policyBy(policyId),existing=state.portingReminders.find(x=>x.policyId===policyId&&!['Ported','Cancelled'].includes(x.status))||{};openForm('Remind for porting','PORTING OPPORTUNITY',`<input type="hidden" name="id" value="${esc(existing.id||'')}"><input type="hidden" name="policyId" value="${esc(policyId)}"><label>Existing company<input name="existingCompany" required value="${esc(existing.existingCompany||p.companyName)}"></label><label>Existing policy<input name="existingPolicy" required value="${esc(existing.existingPolicy||p.policyNumber)}"></label><label>Renewal date<input name="renewalDate" type="date" required value="${esc(existing.renewalDate||p.renewalDueDate)}"></label><div class="two-col"><label>Target company<input name="targetCompany" value="${esc(existing.targetCompany||'')}"></label><label>Target product<input name="targetProduct" value="${esc(existing.targetProduct||'')}"></label></div><label>Reminder date<input name="reminderDate" type="date" required value="${esc(existing.reminderDate||'')}"></label><label>Status<select name="status">${['Pending','Customer Contacted','Appointment Fixed','Porting In Process','Ported','Not Interested','Cancelled'].map(x=>`<option ${existing.status===x?'selected':''}>${x}</option>`).join('')}</select></label><label>Notes<textarea name="notes">${esc(existing.notes||'')}</textarea></label><button class="primary-button">Save porting reminder</button>`,data=>{const c=customerBy(p.customerId),current=state.portingReminders.find(x=>x.id===data.id),record={...current,id:data.id||uid('porting'),policyId:p.id,customerId:c.id,customerName:c.name,existingCompany:data.existingCompany.trim(),existingPolicy:data.existingPolicy.trim(),renewalDate:data.renewalDate,targetCompany:data.targetCompany.trim(),targetProduct:data.targetProduct.trim(),reminderDate:data.reminderDate,status:data.status,notes:data.notes.trim()};state.portingReminders=current?state.portingReminders.map(x=>x.id===record.id?record:x):[record,...state.portingReminders];addActivity(c.id,`Porting reminder · ${record.status}`);closeForm();persist('porting-saved')})}
  function renewPolicyForm(policyId){const p=policyBy(policyId);openForm('Renew policy','PRESERVE HISTORY',`<label>New policy number<input name="policyNumber" required value="${esc(p.policyNumber||'')}"></label><div class="two-col"><label>New start date<input name="startDate" type="date" required value="${esc(p.renewalDueDate||today())}"></label><label>New renewal date<input name="renewalDueDate" type="date" required></label></div><div class="two-col"><label>Company<input name="companyName" required value="${esc(p.companyName||'')}"></label><label>Product<input name="productName" required value="${esc(p.productName||'')}"></label></div><div class="two-col"><label>Category<input name="categoryName" required value="${esc(p.categoryName||'')}"></label><label>New premium ₹<input name="premiumAmount" type="number" required value="${esc(p.premiumAmount||'')}"></label></div><label>Sum insured ₹<input name="sumInsured" type="number" value="${esc(p.sumInsured||'')}"></label><label>Notes<textarea name="notes">${esc(p.notes||'')}</textarea></label><button class="primary-button">Renew and preserve old policy</button>`,data=>{state.policyHistory.unshift({...p,id:uid('history'),sourcePolicyId:p.id,status:'Renewed / Historical',historicalAt:isoNow()});Object.assign(p,{policyNumber:data.policyNumber.trim(),startDate:data.startDate,renewalDueDate:data.renewalDueDate,companyName:data.companyName.trim(),productName:data.productName.trim(),categoryName:data.categoryName.trim(),premiumAmount:Number(data.premiumAmount||0),sumInsured:Number(data.sumInsured||0),notes:data.notes.trim(),status:'Active',hasDocument:false,documentName:'',updatedAt:isoNow()});state.reminders=state.reminders.filter(r=>r.policyId!==p.id);addActivity(p.customerId,`Policy renewed · ${p.productName}`);closeForm();persist('policy-renewed');toast('Renewed · old policy preserved in history')})}

  function snooze(id){choice('Snooze reminder','Choose when this reminder should return.',[{id:'10',label:'10 minutes'},{id:'30',label:'30 minutes'},{id:'60',label:'1 hour'},{id:'tomorrow',label:'Tomorrow'},{id:'custom',label:'Select date'}]);$('#choiceModal').dataset.snooze=id}
  function applySnooze(id,value){const r=state.reminders.find(x=>x.id===id);if(!r)return;let d=new Date();if(value==='tomorrow'){d.setDate(d.getDate()+1);d.setHours(9,0,0,0)}else d=new Date(Date.now()+Number(value)*60000);r.snoozedFrom=r.id;r.id=uid('reminder');r.dueAt=d.toISOString().slice(0,16);r.status='Pending';closeChoice();delete $('#choiceModal').dataset.snooze;persist('reminder-snoozed');toast('Reminder snoozed')}
  function filenameFor(p){const clean=v=>String(v||'Policy').replace(/[^A-Za-z0-9]+/g,'');return `${clean(p.customerName)}_${clean(p.companyName)}_${clean(p.productName)}_${clean(p.policyNumber)}.pdf`}
  function mergeState(imported){ARRAYS.forEach(k=>{const map=new Map((state[k]||[]).map(x=>[x.id,x]));(imported[k]||[]).forEach(x=>{if(!map.has(x.id))map.set(x.id,x)});state[k]=[...map.values()]});if(!state.advisorName)state.advisorName=imported.advisorName||'Advisor'}

  document.addEventListener('click',e=>{
    const t=e.target.closest('button,[data-open-customer],[data-performance]');if(!t)return;
    if(t.dataset.route)route(t.dataset.route);
    if(t.dataset.action==='customer-new'||t.dataset.editCustomer)customerForm(t.dataset.editCustomer);
    if(t.dataset.action==='policy-new'||t.dataset.policyNew!==undefined)policyForm(t.dataset.policyNew||profile.customerId||'');
    if(t.dataset.action==='appointment-new'||t.dataset.appointmentNew!==undefined)appointmentForm(t.dataset.appointmentNew||profile.customerId||'');
    if(t.dataset.action==='reminder-new'||t.dataset.reminderNew!==undefined)reminderForm(t.dataset.reminderNew||profile.customerId||'');
    if(t.dataset.action==='template-new')templateForm();if(t.dataset.templateEdit)templateForm(t.dataset.templateEdit);
    if(t.matches('[data-close-modal]'))closeForm();if(t.matches('[data-close-choice]'))closeChoice();
    if(t.dataset.openCustomer!==undefined){profile.customerId=t.dataset.openCustomer;profile.tab='Overview';route('clients')}
    if(t.hasAttribute('data-close-profile')){profile.customerId=null;$('#clientProfile').classList.add('hidden');renderClients()}
    if(t.dataset.profileTab){profile.tab=t.dataset.profileTab;renderProfile()}
    if(t.dataset.familyNew)familyForm(t.dataset.familyNew);if(t.dataset.familyEdit){const f=state.familyMembers.find(x=>x.id===t.dataset.familyEdit);familyForm(f.customerId,f.id)}
    if(t.dataset.familyDelete){const f=state.familyMembers.find(x=>x.id===t.dataset.familyDelete);if(f&&confirm(`Delete ${f.fullName}?`)){state.familyMembers=state.familyMembers.filter(x=>x.id!==f.id);state.reminders=state.reminders.filter(x=>x.familyMemberId!==f.id);addActivity(f.customerId,`Family member deleted · ${f.fullName}`);persist('family-deleted')}}
    if(t.dataset.policyEdit)policyForm('',t.dataset.policyEdit);if(t.dataset.appointmentEdit){const a=state.appointments.find(x=>x.id===t.dataset.appointmentEdit);appointmentForm(a.customerId,a.id)}
    if(t.dataset.deleteCustomer){const c=customerBy(t.dataset.deleteCustomer);if(c&&confirm(`Delete ${c.name} and all linked policies, family, reminders, appointments and documents?`)){state.policies.filter(p=>p.customerId===c.id&&p.hasDocument).forEach(p=>window.InsureClubNative?.deletePolicyPdf?.(p.id));ARRAYS.forEach(k=>{if(k==='customers')state[k]=state[k].filter(x=>x.id!==c.id);else state[k]=state[k].filter(x=>x.customerId!==c.id)});profile.customerId=null;$('#clientProfile').classList.add('hidden');persist('customer-deleted');toast('Customer and linked records deleted')}}
    if(t.dataset.policyDelete){const p=policyBy(t.dataset.policyDelete);if(p&&confirm(`Delete policy ${p.policyNumber||p.productName}?`)){if(p.hasDocument)window.InsureClubNative?.deletePolicyPdf?.(p.id);state.policies=state.policies.filter(x=>x.id!==p.id);state.reminders=state.reminders.filter(x=>x.policyId!==p.id);state.portingReminders=state.portingReminders.filter(x=>x.policyId!==p.id);addActivity(p.customerId,`Policy deleted · ${p.productName}`);persist('policy-deleted')}}
    if(t.dataset.policyRenew)renewPolicyForm(t.dataset.policyRenew);if(t.dataset.portingNew)portingForm(t.dataset.portingNew);
    if(t.dataset.addPdf)window.InsureClubNative?.selectPolicyPdf?.(t.dataset.addPdf);if(t.dataset.viewPdf)window.InsureClubNative?.viewPolicyPdf?.(t.dataset.viewPdf);if(t.dataset.sharePdf)window.InsureClubNative?.sharePolicyPdf?.(t.dataset.sharePdf);if(t.dataset.downloadPdf){const p=policyBy(t.dataset.downloadPdf);window.InsureClubNative?.downloadPolicyPdf?.(p.id,filenameFor(p))}
    if(t.dataset.deletePdf){const p=policyBy(t.dataset.deletePdf);if(p&&confirm('Delete this policy PDF?')){window.InsureClubNative?.deletePolicyPdf?.(p.id);p.hasDocument=false;p.documentName='';addActivity(p.customerId,`Policy PDF deleted · ${p.productName}`);persist('policy-document-deleted')}}
    if(t.dataset.call)window.InsureClubNative?.callPhone?.(t.dataset.call);
    if(t.dataset.whatsapp){$('#messageClient').value=t.dataset.whatsapp;renderMessages();route('messages')}
    if(t.dataset.messageReminder){const r=state.reminders.find(x=>x.id===t.dataset.messageReminder);$('#messageClient').value=r.customerId;const type=r.type==='Birthday'?'Birthday':r.type==='Renewal'?'Policy Renewal':r.type==='Anniversary'?'Anniversary':'General follow-up';const tpl=state.messageTemplates.find(x=>x.type===type&&x.isDefault)||state.messageTemplates.find(x=>x.type===type);if(tpl)$('#messageTemplate').value=tpl.id;renderMessages();route('messages')}
    if(t.dataset.fixAppointment){const r=state.reminders.find(x=>x.id===t.dataset.fixAppointment);appointmentForm(r.customerId)}
    if(t.dataset.snooze)snooze(t.dataset.snooze);
    if(t.dataset.completeReminder){const r=state.reminders.find(x=>x.id===t.dataset.completeReminder);if(r){r.status='Completed';r.completedAt=isoNow();addActivity(r.customerId,`${r.activity} completed`);persist('reminder-completed')}}
    if(t.dataset.performance){const [a,b]=periodRange(t.dataset.performance);$('#globalSearch').value='';route('search');toast(`Showing policies booked ${fmtDate(a)} to ${fmtDate(b)}`);$('#searchResults').innerHTML=state.policies.filter(p=>p.status==='Active'&&p.startDate>=a&&p.startDate<=b).map(p=>`<article class="result-card" data-open-customer="${p.customerId}"><strong>${esc(p.customerName)} · ${money(p.premiumAmount)}</strong><p>${esc(p.companyName)} · ${esc(p.productName)} · ${fmtDate(p.startDate)}</p></article>`).join('')||empty('No contributing policies','No active booked premium in this period.')}
    if(t.dataset.action==='backup-now'){window.InsureClubAppBackup('manual-backup');toast('Creating verified backup…')}
    if(t.dataset.templateDelete){const item=state.messageTemplates.find(x=>x.id===t.dataset.templateDelete);if(item&&confirm(`Delete template ${item.name}?`)){state.messageTemplates=state.messageTemplates.filter(x=>x.id!==item.id);closeForm();persist('template-deleted')}}
    if(t.dataset.choice){const sid=$('#choiceModal').dataset.snooze;if(t.dataset.choice==='cancel'){closeChoice();delete $('#choiceModal').dataset.snooze}else if(sid){if(t.dataset.choice==='custom'){closeChoice();openForm('Snooze until','REMINDER',`<label>Date & time<input name="dueAt" type="datetime-local" required></label><button class="primary-button">Snooze reminder</button>`,d=>{const r=state.reminders.find(x=>x.id===sid);r.snoozedFrom=r.id;r.id=uid('reminder');r.dueAt=d.dueAt;r.status='Pending';closeForm();persist('reminder-snoozed')})}else applySnooze(sid,t.dataset.choice)}else if(t.dataset.choice==='replace'||t.dataset.choice==='merge')window.InsureClubNative?.commitImport?.(t.dataset.choice);else if(t.dataset.choice==='restore-confirm')window.InsureClubNative?.restoreLatestBackup?.();}
  });
  $('#dynamicForm').addEventListener('submit',e=>{e.preventDefault();if(!formSubmit)return;const data=Object.fromEntries(new FormData(e.currentTarget).entries());formSubmit(data)});
  $('#clientSearch').addEventListener('input',renderClients);$('#globalSearch').addEventListener('input',renderSearch);['searchCompany','searchCategory','searchStatus','searchMonth'].forEach(id=>$(`#${id}`).addEventListener('change',renderSearch));
  $('#reminderFilters').addEventListener('click',e=>{const b=e.target.closest('button');if(b){activeReminderFilter=b.dataset.filter;renderReminders()}});
  ['messageClient','messagePolicy','messageTemplate'].forEach(id=>$(`#${id}`).addEventListener('change',()=>{if(id==='messageClient')fillSelects();resolveTemplate()}));
  $('#copyMessage').addEventListener('click',async()=>{try{await navigator.clipboard.writeText($('#messagePreview').value);toast('Message copied')}catch{toast('Select and copy the message manually')}});
  $('#shareMessage').addEventListener('click',()=>window.InsureClubNative?.shareText?.($('#messagePreview').value));
  $('#sendWhatsApp').addEventListener('click',()=>{const c=customerBy($('#messageClient').value);if(!c)return toast('Choose a customer first');window.InsureClubNative?.openWhatsApp?.(c.phone||'',$('#messagePreview').value)});
  $('#saveAdvisor').addEventListener('click',()=>{state.advisorName=$('#advisorName').value.trim()||'Advisor';persist('advisor-updated')});
  $('#enableNotifications').addEventListener('click',()=>window.InsureClubNative?.requestNotifications?.());$('#notificationSettings').addEventListener('click',()=>window.InsureClubNative?.openNotificationSettings?.());
  $('#exportBackup').addEventListener('click',()=>window.InsureClubNative?.exportData?.(JSON.stringify(state)));$('#importBackup').addEventListener('click',()=>window.InsureClubNative?.inspectImport?.());$('#restoreBackup').addEventListener('click',()=>choice('Restore latest backup','This will replace the current data with the last safe automatic backup. Export first if you need another copy.',[{id:'cancel',label:'Cancel'},{id:'restore-confirm',label:'Restore',danger:true}]));

  window.onNativeNotificationPermission=enabled=>{const b=$('#enableNotifications');b.textContent=enabled?'Reminders active ✓':'Enable reminders';b.classList.toggle('enabled',enabled)};
  window.onNativeReady=raw=>{try{const i=JSON.parse(raw);updateBackupInfo(i)}catch{}};
  window.onBackupCompleted=raw=>{try{const i=JSON.parse(raw);state.backupMetadata=i;localStorage.setItem(STATE_KEY,JSON.stringify(state));updateBackupInfo(i)}catch{}};
  function updateBackupInfo(i){$('#lastBackup').textContent=i?.available&&i.backupDate?`Last safe backup: ${fmtDateTime(i.backupDate)}`:'No backup created yet'}
  window.onExportCompleted=()=>toast('Complete backup exported');window.onNativeFileError=message=>toast(message||'File operation failed');window.onPolicyDownloadCompleted=()=>toast('Policy PDF downloaded');
  window.onImportInspected=raw=>{pendingImportSummary=JSON.parse(raw);choice('Validated InsureClub backup',`Backup: ${fmtDateTime(pendingImportSummary.backupDate)} · ${pendingImportSummary.customers} customers · ${pendingImportSummary.policies} policies · ${pendingImportSummary.familyMembers} family members. Replace current data or merge records with unique IDs?`,[{id:'replace',label:'Replace',danger:true},{id:'merge',label:'Merge safely'}])};
  window.onImportCommitted=(raw,mode,date)=>{const imported=JSON.parse(raw);if(mode==='replace')state=imported;else mergeState(imported);closeChoice();persist('backup-imported');toast(`Backup from ${fmtDateTime(date)} restored`)};
  window.onRestoreReady=(raw,date)=>{state=JSON.parse(raw);closeChoice();persist('automatic-backup-restored');toast(`Restored backup from ${fmtDateTime(date)}`)};
  window.onPolicyDocumentAdded=(policyId,name)=>{const p=policyBy(policyId);if(!p)return;p.hasDocument=true;p.documentName=name;p.documentUpdatedAt=isoNow();addActivity(p.customerId,`Policy PDF added · ${p.productName}`);persist('policy-document-added');toast('Policy PDF stored safely')};

  ensureAutomaticReminders();localStorage.setItem(STATE_KEY,JSON.stringify(state));renderAll();
  if(window.InsureClubNative?.notificationsEnabled)window.onNativeNotificationPermission(window.InsureClubNative.notificationsEnabled());
})();
